Ver el código en Python
espiralE = {
  const inicio = inicioE.endsWith("10") ? 10 : 0;
  const correr = (subasta, desde) =&gt; simular(mercadoConPoliticas({subasta_fncer: subasta, inicio_subasta: desde, duracion_subasta: 20}), {tFinal: 40, paso: 0.05});
  const r = correr(subastaE, inicio);
  const otro = correr(subastaE, inicio === 0 ? 10 : 0);
  const v = r.variables;
  const k30 = Math.round(30 / 0.05);
  const x = [], y = [];
  r.tiempo.forEach((t, k) =&gt; { if (v.capacidad_fncer[k] &gt; 1000 && v.capacidad_fncer[k] &lt; 8000) { x.push(t); y.push(Math.log(v.capacidad_fncer[k])); } });
  const tasa = x.length &gt; 10 ? regresionLineal(x, y).pendiente : null;
  return {
    filas: r.tiempo.map((t, k) =&gt; ({t, K: v.capacidad_fncer[k], Q: v.fncer_acumulada[k], c: v.costo_fncer[k]})),
    otro: otro.tiempo.map((t, k) =&gt; ({t, K: otro.variables.capacidad_fncer[k]})),
    cap30: v.capacidad_fncer[k30], costo30: v.costo_fncer[k30], costoOtro30: otro.variables.costo_fncer[k30], tasa,
  };
}









